SELECT * FROM cut_approval_instance
WHERE tenant_id = #{query.tenantId}
  AND task_id = #{query.taskId}
  AND plan_revision_id = #{query.planRevisionId}
  AND deleted = b'0'
FOR UPDATE

SELECT * FROM cut_approval_instance
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.approvalInstanceId}
  AND deleted = b'0'
FOR UPDATE

mapper.update:
UPDATE cut_approval_instance
SET hold_reason_code = #{query.holdReasonCode},
    version = #{query.expectedVersion} + 1,
    updater = #{query.updater},
    update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.approvalInstanceId}
  AND status_code = 'PENDING'
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
